# docx uses UTF-16 or the XML inside is deflated. Let's use node's zlib to inflate
node -e "
const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');

// Use yauzl or just manually parse the zip
// Actually let's use the built-in zlib + manual zip parsing

function readDocxText(filepath) {
  const buf = fs.readFileSync(filepath);
  // Find the word/document.xml entry in the ZIP
  let offset = 0;
  const entries = [];
  while (offset < buf.length - 4) {
    if (buf.readUInt32LE(offset) === 0x04034b50) { // local file header
      const compMethod = buf.readUInt16LE(offset + 8);
      const compSize = buf.readUInt32LE(offset + 18);
      const uncompSize = buf.readUInt32LE(offset + 22);
      const fnLen = buf.readUInt16LE(offset + 26);
      const extraLen = buf.readUInt16LE(offset + 28);
      const filename = buf.toString('utf8', offset + 30, offset + 30 + fnLen);
      const dataStart = offset + 30 + fnLen + extraLen;
      const dataEnd = dataStart + compSize;

      if (filename === 'word/document.xml') {
        const compData = buf.slice(dataStart, dataEnd);
        if (compMethod === 8) { // deflated
          const zlib = require('zlib');
          const inflated = zlib.inflateRawSync(compData);
          return inflated.toString('utf8');
        } else {
          return compData.toString('utf8');
        }
      }
      offset = dataEnd;
    } else {
      offset++;
    }
  }
  return '';
}

const dir = '/workspace/testbed/docs/';
const files = fs.readdirSync(dir).filter(f => f.endsWith('.docx'));
for (const f of files) {
  const text = readDocxText(path.join(dir, f));
  const plainText = text.replace(/<[^>]+>/g, ' ').replace(/\\s+/g, ' ').trim();
  console.log('=== ' + f + ' ===');
  console.log(plainText.substring(0, 500));
  console.log('');
}
