const PDFDocument = require('pdfkit');
const fs = require('fs');

const doc = new PDFDocument({ margin: 50 });
const output = fs.createWriteStream('/workspace/testbed/docs/maya_chen_customer_report.pdf');
doc.pipe(output);

// Title
doc.fontSize(20).font('Helvetica-Bold').text('Customer Activity Report', { align: 'center' });
doc.moveDown(0.5);

// Customer info
doc.fontSize(14).font('Helvetica-Bold').text('Maya Chen');
doc.moveDown(0.3);
doc.fontSize(10).font('Helvetica');
doc.text('Email: maya.chen@example.com');
doc.text('Loyalty Tier: Gold');
doc.text('Store Credit: \$0');
doc.moveDown(0.5);

// Divider
doc.moveTo(50, doc.y).lineTo(562, doc.y).stroke();
doc.moveDown(0.5);

// Orders
const orders = [
  { id: 'ORD-6C71B1', date: '2026-09-02', status: 'cancelled', total: '\$79',  items: 'Anker Portable Bluetooth Speaker' },
  { id: 'ORD-5B048F', date: '2026-09-02', status: 'confirmed', total: '\$108', items: 'Anker Portable Bluetooth Speaker, LogiTech Wireless Mouse M310' },
  { id: 'ORD-12AAA3', date: '2026-09-02', status: 'cancelled', total: '\$39',  items: 'Wireless Ergonomic Mouse' },
  { id: 'ORD-542FDA', date: '2026-09-02', status: 'confirmed', total: '\$68',  items: 'OXO SoftWorks 3-Piece Mixing Bowl Set, ThermoPro Digital Meat Thermometer' },
  { id: 'ORD-D7E869', date: '2026-09-02', status: 'confirmed', total: '\$71',  items: 'LogiTech Wireless Mouse M310, OXO SoftWorks 3-Piece Mixing Bowl Set' },
  { id: 'ORD-C31654', date: '2026-09-02', status: 'confirmed', total: '\$29',  items: 'Wireless Mouse' },
  { id: 'ORD-CCC96C', date: '2026-09-02', status: 'confirmed', total: '\$201', items: 'LogiTech Wireless Mouse M310, OXO SoftWorks 3-Piece Mixing Bowl Set, Aurora Smart Desk Lamp Pro' },
];

doc.fontSize(12).font('Helvetica-Bold').text('Orders');
doc.moveDown(0.3);

// Table header
const colX = { order: 50, date: 148, status: 230, total: 310, items: 365 };
const headerY = doc.y;
doc.fontSize(9).font('Helvetica-Bold');
doc.text('Order', colX.order, headerY, { width: 90 });
doc.text('Date', colX.date, headerY, { width: 80 });
doc.text('Status', colX.status, headerY, { width: 75 });
doc.text('Total', colX.total, headerY, { width: 50 });
doc.text('Items', colX.items, headerY, { width: 197 });
doc.moveDown(0.2);

// Header underline
const lineY = doc.y;
doc.moveTo(50, lineY).lineTo(562, lineY).stroke();
doc.moveDown(0.3);

// Table rows
doc.font('Helvetica').fontSize(9);
orders.forEach((o) => {
  const rowY = doc.y;
  // Calculate the height needed for the items column (may wrap)
  const itemsHeight = doc.heightOfString(o.items, { width: 197 });
  const rowHeight = Math.max(itemsHeight, 12);

  // Color the status
  doc.text(o.id, colX.order, rowY, { width: 90 });
  doc.text(o.date, colX.date, rowY, { width: 80 });

  const statusColor = o.status === 'cancelled' ? 'red' : 'green';
  doc.fillColor(statusColor).text(o.status, colX.status, rowY, { width: 75 });
  doc.fillColor('black');

  doc.text(o.total, colX.total, rowY, { width: 50 });
  doc.text(o.items, colX.items, rowY, { width: 197 });

  doc.y = rowY + rowHeight + 6;
});

doc.moveDown(1);

// Summary
doc.moveTo(50, doc.y).lineTo(562, doc.y).stroke();
doc.moveDown(0.5);
doc.fontSize(10).font('Helvetica-Bold').text('Summary');
doc.moveDown(0.3);
doc.fontSize(9).font('Helvetica');
doc.text('Total Orders: 7');
doc.text('Confirmed: 5');
doc.text('Cancelled: 2');
doc.text('Total Value (confirmed): \$477');

doc.end();

output.on('finish', () => {
  console.log('PDF created successfully: /workspace/testbed/docs/maya_chen_customer_report.pdf');
  const stats = fs.statSync('/workspace/testbed/docs/maya_chen_customer_report.pdf');
  console.log('File size: ' + (stats.size / 1024).toFixed(1) + ' KB');
});
